"""Random arrays and shifts for the rotation.

The shift is what this problem is really about, so the builders vary it
deliberately: inside the array, past its end, and an exact multiple of its
length. The values themselves are just cargo.
"""


def generate(rng, count):
    builders = (_partial_turn, _past_the_end, _whole_turns, _long_array)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, shift, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n%d\n" % (len(values),
                                    " ".join(str(v) for v in values), shift),
        "description": description,
    }


def _values(rng, how_many):
    return [rng.randint(-99, 99) for _ in range(how_many)]


def _partial_turn(rng, index):
    values = _values(rng, rng.randint(5, 10))
    return _case("a partial turn #%d" % index, values,
                 rng.randint(1, len(values) - 1))


def _past_the_end(rng, index):
    values = _values(rng, rng.randint(4, 8))
    shift = len(values) * rng.randint(1, 4) + rng.randint(1, len(values) - 1)
    return _case("a shift past the end #%d" % index, values, shift,
                 "The shift is bigger than the array, so it has to come down "
                 "modulo the length before anything moves.")


def _whole_turns(rng, index):
    values = _values(rng, rng.randint(3, 8))
    return _case("whole turns only #%d" % index, values,
                 len(values) * rng.randint(1, 5),
                 "An exact multiple of the length: the array comes back "
                 "unchanged.")


def _long_array(rng, index):
    values = _values(rng, rng.randint(11, 16))
    return _case("a longer array #%d" % index, values,
                 rng.randint(1, len(values) - 1))
